"""Shared schema and colors for parental and contact phase evidence.

Rukki's trio input is maternal-first. Keep that order in every intermediate
file; the workflow independently selects paternal paths as final haplotype 1.
"""

MATERNAL_COLOR = "#FF8888"
PATERNAL_COLOR = "#8888FF"
MIXED_COLOR = "#FFFF00"
UNASSIGNED_COLOR = "#AAAAAA"
PHASE_COUNT_HEADER = "node\tmaternal\tpaternal\tmaternal:paternal\tcolor"

MATERNAL_COLUMNS = ("maternal", "mat")
PATERNAL_COLUMNS = ("paternal", "pat")


def _column_index(header, accepted, description):
    normalized = [field.lower() for field in header]
    for name in accepted:
        if name in normalized:
            return normalized.index(name)
    raise ValueError(
        f"phase evidence header has no {description} column "
        f"(accepted names: {', '.join(accepted)})"
    )


def read_phase_counts(path):
    """Return node -> (maternal, paternal), using names rather than position."""
    result = {}
    with open(path, encoding="utf-8") as stream:
        header = stream.readline().split()
        if not header:
            raise ValueError(f"empty phase evidence file: {path}")
        node_column = _column_index(header, ("node", "contig"), "node")
        maternal_column = _column_index(header, MATERNAL_COLUMNS, "maternal")
        paternal_column = _column_index(header, PATERNAL_COLUMNS, "paternal")
        required = max(node_column, maternal_column, paternal_column)

        for line_number, line in enumerate(stream, 2):
            fields = line.split()
            if not fields:
                continue
            if len(fields) <= required:
                raise ValueError(
                    f"{path}:{line_number}: expected at least {required + 1} columns"
                )
            result[fields[node_column]] = (
                int(fields[maternal_column]),
                int(fields[paternal_column]),
            )
    return result


def marker_color(maternal, paternal, fraction, minimum_total):
    """Apply Verkko's conservative marker policy using canonical order."""
    total = maternal + paternal
    if total <= minimum_total:
        return UNASSIGNED_COLOR
    if maternal > total * fraction:
        return MATERNAL_COLOR
    if paternal > total * fraction:
        return PATERNAL_COLOR
    return MIXED_COLOR


def format_phase_counts(node, maternal, paternal, color):
    """Format the five columns consumed by Rukki and Bandage."""
    return f"{node}\t{maternal}\t{paternal}\t{maternal}:{paternal}\t{color}"
